import * as React from "react";
import { createRoot } from "react-dom/client";
import { OfficeAdapterContext } from "@bluebook/shared";
import { excelAdapter } from "../adapters/excelAdapter";
import App from "./components/App";

import "@bluebook/shared/src/styles.css";

/* global document, Office, module, require, HTMLElement */

const rootElement: HTMLElement | null = document.getElementById("container");
const root = rootElement ? createRoot(rootElement) : undefined;

Office.onReady(() => {
  root?.render(
    <OfficeAdapterContext.Provider value={excelAdapter}>
      <App />
    </OfficeAdapterContext.Provider>
  );
});

if ((module as any).hot) {
  (module as any).hot.accept("./components/App", () => {
    const NextApp = require("./components/App").default;
    root?.render(NextApp);
  });
}
