import * as React from "react";
import { ChatMessage as ChatMessageType } from "../types";
import { createChatClient } from "../api/client";
import { ChatConnection } from "../api/websocket-client";
import { syncDocumentSnapshot } from "../api/sync";
import { useOfficeAdapter } from "../context/OfficeAdapterContext";
import ChatMessage from "./ChatMessage";
import ChatInput from "./ChatInput";

interface ChatPaneProps {
  apiBaseUrl?: string;
}

function generateId(): string {
  return Date.now().toString(36) + Math.random().toString(36).slice(2);
}

const ChatPane: React.FC<ChatPaneProps> = ({ apiBaseUrl }) => {
  const [messages, setMessages] = React.useState<ChatMessageType[]>([]);
  const [isLoading, setIsLoading] = React.useState(false);
  const messagesEndRef = React.useRef<HTMLDivElement>(null);
  const abortRef = React.useRef<AbortController | null>(null);
  const chatRef = React.useRef<ChatConnection>(new ChatConnection());
  const adapter = useOfficeAdapter();
  const mockClient = React.useMemo(() => createChatClient(apiBaseUrl), [apiBaseUrl]);

  const handleStop = () => {
    if (abortRef.current) {
      abortRef.current.abort();
      abortRef.current = null;
    }
  };

  React.useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages]);

  const handleSubmit = async (commitNote: string) => {
    const userMessage: ChatMessageType = {
      id: generateId(),
      role: "user",
      content: `/submit ${commitNote}`,
      timestamp: Date.now(),
    };
    setMessages((prev) => [...prev, userMessage]);

    try {
      const ctx = await adapter.getDocumentContext();
      const content = (ctx.bodyText as string) || "";
      if (adapter.getDocumentName) {
        const docInfo = await adapter.getDocumentName();
        await syncDocumentSnapshot(
          docInfo.path,
          docInfo.name,
          "",
          content,
          commitNote,
        );
        setMessages((prev) => [...prev, {
          id: generateId(),
          role: "assistant",
          content: `Changes submitted: "${commitNote}"`,
          timestamp: Date.now(),
        }]);
      }
    } catch {
      setMessages((prev) => [...prev, {
        id: generateId(),
        role: "assistant",
        content: "Failed to submit changes. Is the Bluebook desktop app running?",
        timestamp: Date.now(),
      }]);
    }
  };

  const handleSend = async (content: string) => {
    // Intercept /submit command
    if (content.startsWith("/submit")) {
      const note = content.slice(7).trim() || "Manual submission";
      await handleSubmit(note);
      return;
    }

    const userMessage: ChatMessageType = {
      id: generateId(),
      role: "user",
      content,
      timestamp: Date.now(),
    };

    const streamingMessage: ChatMessageType = {
      id: generateId(),
      role: "assistant",
      content: "",
      timestamp: Date.now(),
      isStreaming: true,
    };

    setMessages((prev) => [...prev, userMessage, streamingMessage]);
    setIsLoading(true);
    abortRef.current = new AbortController();

    try {
      let selectedContent: string | undefined;
      try {
        selectedContent = await adapter.getSelectedContent();
      } catch {
        // No selection available
      }

      // Capture current slide image for PowerPoint vision analysis
      let slideImage: string | null = null;
      if (adapter.getSlideImage) {
        try {
          slideImage = await adapter.getSlideImage();
        } catch {
          // Slide image capture not available
        }
      }

      // // Enable track changes before Claude makes edits
      // if (adapter.enableTrackChanges) {
      //   await adapter.enableTrackChanges();
      // }

      // Get current document info (if available)
      let documentName: string | null = null;
      let documentPath: string | null = null;
      if (adapter.getDocumentName) {
        try {
          const docInfo = await adapter.getDocumentName();
          documentName = docInfo.name;
          documentPath = docInfo.path;
        } catch {
          // Document name not available
        }
      }

      // Use server-side Claude orchestration via persistent WebSocket
      const result = await chatRef.current.sendMessage(
        adapter.appType,
        content,
        selectedContent || null,
        (action) => adapter.executeAction(action),
        (status) => {
          setMessages((prev) =>
            prev.map((msg) =>
              msg.id === streamingMessage.id
                ? { ...msg, content: status, isStreaming: true }
                : msg
            )
          );
        },
        abortRef.current?.signal,
        slideImage,
        documentName,
        documentPath,
      );

      // // Disable track changes after Claude is done
      // if (adapter.disableTrackChanges) {
      //   await adapter.disableTrackChanges();
      // }

      setMessages((prev) =>
        prev.map((msg) =>
          msg.id === streamingMessage.id
            ? {
                id: generateId(),
                role: "assistant" as const,
                content: result.text || "",
                timestamp: Date.now(),
                isStreaming: false,
                sources: result.sources.length > 0 ? result.sources : undefined,
              }
            : msg
        )
      );
    } catch (error) {
      const isAborted = error instanceof DOMException && error.name === "AbortError";
      let errorContent: string;
      if (isAborted) {
        errorContent = "Stopped.";
      } else if (error instanceof Error && error.message.includes("WebSocket connection failed")) {
        errorContent = "Could not connect to Bluebook. Make sure the desktop app is running and your API key is set in Settings \u2192 Connections.";
      } else {
        errorContent = error instanceof Error ? error.message : "Something went wrong. Please try again.";
      }
      setMessages((prev) =>
        prev.map((msg) =>
          msg.id === streamingMessage.id
            ? { ...msg, content: errorContent, isStreaming: false }
            : msg
        )
      );
    } finally {
      abortRef.current = null;
      // // Ensure track changes is off even if something failed
      // if (adapter.disableTrackChanges) {
      //   try { await adapter.disableTrackChanges(); } catch { /* ignore */ }
      // }
      setIsLoading(false);
    }
  };

  return (
    <div className="flex h-screen flex-col bg-background font-sans">
      {/* Messages */}
      <div className="flex-1 relative overflow-hidden">
        {messages.length === 0 && !isLoading ? (
          <div className="absolute inset-0 flex flex-col items-center justify-center p-8 text-center">
            <div className="mb-6">
              <svg width="64" height="64" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="0.75" strokeLinecap="round" strokeLinejoin="round" className="text-muted-foreground/40">
                <path d="M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z" />
              </svg>
            </div>
            <h2 className="text-base font-semibold mb-2">Let's Get Started</h2>
            <p className="text-sm text-muted-foreground max-w-[240px]">
              Ask questions, work on your document, or discuss your project
            </p>
          </div>
        ) : (
          <div className="h-full overflow-y-auto">
            {messages.map((msg) => (
              <ChatMessage key={msg.id} message={msg} />
            ))}
            <div ref={messagesEndRef} />
          </div>
        )}
      </div>

      {/* Input */}
      <div className="border-t">
        <ChatInput
          onSend={handleSend}
          disabled={isLoading}
          onStop={isLoading ? handleStop : undefined}
        />
      </div>
    </div>
  );
};

export default ChatPane;
