/* global Excel, Office */

import { OfficeAdapter, OfficeAction } from "@bluebook/shared";

function coerce2DArray(value: unknown, fieldName: string): unknown[][] {
  // Already a 2D array?
  if (Array.isArray(value) && value.every(row => Array.isArray(row))) {
    const cols = (value[0] as unknown[])?.length ?? 0;
    for (let i = 0; i < value.length; i++) {
      const row = value[i] as unknown[];
      if (row.length !== cols) {
        throw new Error(`${fieldName} must be rectangular: row ${i} has ${row.length} cells but row 0 has ${cols}.`);
      }
    }
    return value as unknown[][];
  }
  // Attempt to coerce from JSON string (model sometimes produces this under token pressure)
  if (typeof value === "string") {
    try {
      const parsed = JSON.parse(value);
      if (Array.isArray(parsed) && parsed.every(row => Array.isArray(row))) {
        return parsed as unknown[][];
      }
    } catch {
      // fall through to error
    }
    throw new Error(`${fieldName} was provided as a string instead of a 2D array. Retry with a proper 2D array like [["value1", "value2"], ["value3", "value4"]].`);
  }
  throw new Error(`${fieldName} must be a 2D array. Got ${typeof value}.`);
}

export const excelAdapter: OfficeAdapter = {
  appType: "excel",

  async getDocumentName(): Promise<{ path: string; name: string }> {
    const url = Office.context.document.url || "Untitled";
    const parts = url.split(/[/\\]/);
    const name = parts[parts.length - 1] || "Untitled";
    return { path: url, name };
  },

  async getSelectedContent(): Promise<string> {
    return Excel.run(async (context) => {
      const range = context.workbook.getSelectedRange();
      range.load("values,address");
      await context.sync();
      const rows = (range.values as unknown[][]).map((row) => row.join("\t"));
      return `${range.address}\n${rows.join("\n")}`;
    });
  },

  async getDocumentContext(): Promise<Record<string, unknown>> {
    return Excel.run(async (context) => {
      const sheet = context.workbook.worksheets.getActiveWorksheet();
      const usedRange = sheet.getUsedRangeOrNullObject();
      sheet.load("name");
      usedRange.load("values,address");
      await context.sync();

      if (usedRange.isNullObject) {
        return { sheetName: sheet.name, bodyText: "" };
      }

      const rows = (usedRange.values as unknown[][]).map((row) => row.join("\t"));
      return {
        sheetName: sheet.name,
        bodyText: rows.join("\n"),
        address: usedRange.address,
      };
    });
  },

  async executeAction(action: OfficeAction): Promise<unknown> {
    switch (action.type) {

      // --- Cell Operations ---

      case "writeCells":
        await Excel.run(async (context) => {
          const sheet = action.params.sheet
            ? context.workbook.worksheets.getItem(action.params.sheet as string)
            : context.workbook.worksheets.getActiveWorksheet();
          const startCell = action.params.startCell as string;
          const values = coerce2DArray(action.params.values, "values");
          const rows = values.length;
          const cols = values[0]?.length || 1;
          const range = sheet.getRangeByIndexes(
            cellToRowCol(startCell).row,
            cellToRowCol(startCell).col,
            rows,
            cols,
          );
          range.values = values;
          await context.sync();
        });
        break;

      case "readRange":
        return Excel.run(async (context) => {
          const sheet = action.params.sheet
            ? context.workbook.worksheets.getItem(action.params.sheet as string)
            : context.workbook.worksheets.getActiveWorksheet();
          const range = sheet.getRange(action.params.address as string);
          const includeFormulas = action.params.include_formulas === true;
          const loadSpec = includeFormulas ? "values,address,text,formulas" : "values,address,text";
          range.load(loadSpec);
          await context.sync();
          const result: Record<string, unknown> = {
            address: range.address,
            values: range.values,
            text: range.text,
          };
          if (includeFormulas) {
            result.formulas = range.formulas;
          }
          return result;
        });

      case "readFormulas":
        return Excel.run(async (context) => {
          const sheet = action.params.sheet
            ? context.workbook.worksheets.getItem(action.params.sheet as string)
            : context.workbook.worksheets.getActiveWorksheet();
          const range = sheet.getRange(action.params.address as string);
          range.load("address,formulas");
          await context.sync();
          return {
            address: range.address,
            formulas: range.formulas,
          };
        });

      case "clearRange":
        await Excel.run(async (context) => {
          const sheet = action.params.sheet
            ? context.workbook.worksheets.getItem(action.params.sheet as string)
            : context.workbook.worksheets.getActiveWorksheet();
          const range = sheet.getRange(action.params.address as string);
          range.clear();
          await context.sync();
        });
        break;

      case "clearCells":
        return Excel.run(async (context) => {
          const sheet = action.params.sheet
            ? context.workbook.worksheets.getItem(action.params.sheet as string)
            : context.workbook.worksheets.getActiveWorksheet();
          const addresses = action.params.addresses as string[];

          if (!Array.isArray(addresses) || addresses.length === 0) {
            throw new Error("clear_cells requires a non-empty array of cell addresses.");
          }

          const ranges = addresses.map((addr) => sheet.getRange(addr));
          for (const range of ranges) {
            range.clear(Excel.ClearApplyTo.contents);
          }
          await context.sync();

          return { cleared: addresses.length, addresses };
        });

      case "getSelectedRange":
        return Excel.run(async (context) => {
          const range = context.workbook.getSelectedRange();
          range.load("values,address,text");
          await context.sync();
          return {
            address: range.address,
            values: range.values,
            text: range.text,
          };
        });

      // --- Formulas ---

      case "writeFormulas":
        await Excel.run(async (context) => {
          const sheet = action.params.sheet
            ? context.workbook.worksheets.getItem(action.params.sheet as string)
            : context.workbook.worksheets.getActiveWorksheet();
          const startCell = action.params.startCell as string;
          const formulas = coerce2DArray(action.params.formulas, "formulas") as string[][];
          const rows = formulas.length;
          const cols = formulas[0]?.length || 1;
          const range = sheet.getRangeByIndexes(
            cellToRowCol(startCell).row,
            cellToRowCol(startCell).col,
            rows,
            cols,
          );
          range.formulas = formulas;
          await context.sync();
        });
        break;

      case "replaceInFormulas":
        return Excel.run(async (context) => {
          const sheet = action.params.sheet
            ? context.workbook.worksheets.getItem(action.params.sheet as string)
            : context.workbook.worksheets.getActiveWorksheet();
          const range = sheet.getRange(action.params.address as string);
          const find = action.params.find as string;
          const replace = action.params.replace as string;

          range.load("formulas,rowCount,columnCount,address");
          await context.sync();

          const formulas = range.formulas as string[][];
          let replacementCount = 0;
          const cellsChanged: string[] = [];

          const newFormulas = formulas.map((row, r) =>
            row.map((cell, c) => {
              if (typeof cell === "string" && cell.startsWith("=") && cell.includes(find)) {
                replacementCount++;
                if (cellsChanged.length < 20) {
                  cellsChanged.push(`row ${r + 1}, col ${c + 1}`);
                }
                return cell.split(find).join(replace);
              }
              return cell;
            }),
          );

          if (replacementCount > 0) {
            range.formulas = newFormulas;
            await context.sync();
          }

          return {
            range: range.address,
            replacements: replacementCount,
            cellsChanged: cellsChanged.slice(0, 20),
            note: replacementCount === 0
              ? `No formulas in range contained the string "${find}".`
              : replacementCount > 20
                ? `Showing first 20 of ${replacementCount} changes.`
                : undefined,
          };
        });

      // --- Formatting ---

      case "formatRange":
        await Excel.run(async (context) => {
          const sheet = action.params.sheet
            ? context.workbook.worksheets.getItem(action.params.sheet as string)
            : context.workbook.worksheets.getActiveWorksheet();
          const range = sheet.getRange(action.params.address as string);
          const fmt = action.params;
          if (fmt.numberFormat !== undefined) {
            range.load("rowCount,columnCount");
            await context.sync();
          }
          if (fmt.bold !== undefined) range.format.font.bold = fmt.bold as boolean;
          if (fmt.italic !== undefined) range.format.font.italic = fmt.italic as boolean;
          if (fmt.underline !== undefined) {
            range.format.font.underline = (fmt.underline as boolean) ? Excel.RangeUnderlineStyle.single : Excel.RangeUnderlineStyle.none;
          }
          if (fmt.fontSize !== undefined) range.format.font.size = fmt.fontSize as number;
          if (fmt.fontName !== undefined) range.format.font.name = fmt.fontName as string;
          if (fmt.fontColor !== undefined) range.format.font.color = fmt.fontColor as string;
          if (fmt.fillColor !== undefined) range.format.fill.color = fmt.fillColor as string;
          if (fmt.numberFormat !== undefined) {
            const nf = fmt.numberFormat as string;
            range.numberFormat = Array.from({ length: range.rowCount }, () => Array(range.columnCount).fill(nf));
          }
          if (fmt.horizontalAlignment !== undefined) {
            range.format.horizontalAlignment = fmt.horizontalAlignment as Excel.HorizontalAlignment;
          }
          if (fmt.wrapText !== undefined) range.format.wrapText = fmt.wrapText as boolean;
          await context.sync();
        });
        break;

      case "readFormat":
        return Excel.run(async (context) => {
          const sheet = action.params.sheet
            ? context.workbook.worksheets.getItem(action.params.sheet as string)
            : context.workbook.worksheets.getActiveWorksheet();
          const range = sheet.getRange(action.params.address as string);
          range.load("numberFormat");
          range.format.load("horizontalAlignment,verticalAlignment,wrapText,rowHeight,columnWidth");
          range.format.font.load("bold,italic,underline,size,name,color,strikethrough");
          range.format.fill.load("color");
          await context.sync();
          return {
            font: {
              bold: range.format.font.bold,
              italic: range.format.font.italic,
              underline: range.format.font.underline,
              strikethrough: range.format.font.strikethrough,
              size: range.format.font.size,
              name: range.format.font.name,
              color: range.format.font.color,
            },
            fill: {
              color: range.format.fill.color,
            },
            numberFormat: range.numberFormat,
            horizontalAlignment: range.format.horizontalAlignment,
            verticalAlignment: range.format.verticalAlignment,
            wrapText: range.format.wrapText,
          };
        });

      case "autoFitColumns":
        await Excel.run(async (context) => {
          const sheet = action.params.sheet
            ? context.workbook.worksheets.getItem(action.params.sheet as string)
            : context.workbook.worksheets.getActiveWorksheet();
          if (action.params.address) {
            const range = sheet.getRange(action.params.address as string);
            range.format.autofitColumns();
          } else {
            const usedRange = sheet.getUsedRange();
            usedRange.format.autofitColumns();
          }
          await context.sync();
        });
        break;

      // --- Worksheet Operations ---

      case "addWorksheet":
        await Excel.run(async (context) => {
          const sheet = context.workbook.worksheets.add(action.params.name as string | undefined);
          sheet.activate();
          await context.sync();
        });
        break;

      case "duplicateWorksheet":
        return Excel.run(async (context) => {
          const source = context.workbook.worksheets.getItem(action.params.sourceSheet as string);
          const copy = source.copy("End");
          copy.load("name");
          await context.sync();
          return { name: copy.name };
        });

      case "renameWorksheet":
        await Excel.run(async (context) => {
          const sheet = action.params.currentName
            ? context.workbook.worksheets.getItem(action.params.currentName as string)
            : context.workbook.worksheets.getActiveWorksheet();
          sheet.name = action.params.newName as string;
          await context.sync();
        });
        break;

      case "moveWorksheet":
        await Excel.run(async (context) => {
          const sheet = context.workbook.worksheets.getItem(action.params.name as string);
          sheet.position = action.params.position as number;
          await context.sync();
        });
        break;

      case "deleteWorksheet":
        await Excel.run(async (context) => {
          const sheet = context.workbook.worksheets.getItem(action.params.name as string);
          sheet.delete();
          await context.sync();
        });
        break;

      case "getWorksheets":
        return Excel.run(async (context) => {
          const sheets = context.workbook.worksheets;
          sheets.load("items/name,items/position");
          await context.sync();
          return sheets.items.map((s) => ({
            name: s.name,
            position: s.position,
          }));
        });

      // --- Freeze Panes ---

      case "freezePanes":
        await Excel.run(async (context) => {
          const sheet = action.params.sheet
            ? context.workbook.worksheets.getItem(action.params.sheet as string)
            : context.workbook.worksheets.getActiveWorksheet();

          if (action.params.unfreeze === true) {
            sheet.freezePanes.unfreeze();
            await context.sync();
            return;
          }

          const rows = action.params.rows as number | undefined;
          const columns = action.params.columns as number | undefined;

          if (rows !== undefined && columns !== undefined) {
            const freezeRange = sheet.getRange(`A1:${colIndexToLetter(columns - 1)}${rows}`);
            sheet.freezePanes.freezeAt(freezeRange);
          } else if (rows !== undefined) {
            sheet.freezePanes.freezeRows(rows);
          } else if (columns !== undefined) {
            sheet.freezePanes.freezeColumns(columns);
          }
          await context.sync();
        });
        break;

      // --- Table Operations ---

      case "insertTable":
        await Excel.run(async (context) => {
          const sheet = action.params.sheet
            ? context.workbook.worksheets.getItem(action.params.sheet as string)
            : context.workbook.worksheets.getActiveWorksheet();
          const address = action.params.address as string;
          const hasHeaders = (action.params.hasHeaders as boolean) !== false;
          const table = sheet.tables.add(address, hasHeaders);
          if (action.params.name) {
            table.name = action.params.name as string;
          }
          await context.sync();
        });
        break;

      case "addTableRow":
        await Excel.run(async (context) => {
          const sheet = action.params.sheet
            ? context.workbook.worksheets.getItem(action.params.sheet as string)
            : context.workbook.worksheets.getActiveWorksheet();
          const table = sheet.tables.getItem(action.params.tableName as string);
          const values = action.params.values as (string | number | boolean)[];
          table.rows.add(undefined, [values]);
          await context.sync();
        });
        break;

      // --- Search ---

      case "findInSheet":
        return Excel.run(async (context) => {
          const sheet = action.params.sheet
            ? context.workbook.worksheets.getItem(action.params.sheet as string)
            : context.workbook.worksheets.getActiveWorksheet();
          const usedRange = sheet.getUsedRange();
          usedRange.load("values,address,rowIndex,columnIndex");
          sheet.load("name");
          await context.sync();

          const searchText = (action.params.searchText as string).toLowerCase();
          const matches: string[] = [];
          const values = usedRange.values as unknown[][];
          for (let r = 0; r < values.length; r++) {
            for (let c = 0; c < values[r].length; c++) {
              const cellVal = String(values[r][c]).toLowerCase();
              if (cellVal.includes(searchText)) {
                const colLetter = colIndexToLetter(c + usedRange.columnIndex);
                matches.push(`${sheet.name}!${colLetter}${r + usedRange.rowIndex + 1}: ${values[r][c]}`);
              }
            }
          }
          return {
            count: matches.length,
            matches: matches.slice(0, 50),
          };
        });

      // --- Stats ---

      case "getSheetStats":
        return Excel.run(async (context) => {
          const sheet = action.params.sheet
            ? context.workbook.worksheets.getItem(action.params.sheet as string)
            : context.workbook.worksheets.getActiveWorksheet();
          const usedRange = sheet.getUsedRangeOrNullObject();
          sheet.load("name");
          usedRange.load("rowCount,columnCount,address");
          await context.sync();

          if (usedRange.isNullObject) {
            return {
              sheet: sheet.name,
              rows: 0,
              columns: 0,
              address: null,
            };
          } else {
            return {
              sheet: sheet.name,
              rows: usedRange.rowCount,
              columns: usedRange.columnCount,
              address: usedRange.address,
            };
          }
        });

      case "findLastRow":
        return Excel.run(async (context) => {
          const sheet = action.params.sheet
            ? context.workbook.worksheets.getItem(action.params.sheet as string)
            : context.workbook.worksheets.getActiveWorksheet();
          const column = action.params.column as string | undefined;

          // getUsedRange(true) = valuesOnly, ignoring empty formatted cells
          const usedRange = sheet.getUsedRangeOrNullObject(true);
          sheet.load("name");
          usedRange.load("rowIndex,columnIndex,rowCount,columnCount,values,address");
          await context.sync();

          if (usedRange.isNullObject) {
            return {
              sheet: sheet.name,
              lastRow: null,
              message: "Sheet is empty",
            };
          }

          if (!column) {
            return {
              sheet: sheet.name,
              lastRow: usedRange.rowIndex + usedRange.rowCount,
              dataRange: usedRange.address,
            };
          }

          // Parse column letter to 0-based index
          const colMatch = column.match(/^\$?([A-Z]+)/i);
          if (!colMatch) throw new Error(`Invalid column: "${column}"`);
          const colLetter = colMatch[1].toUpperCase();
          let colIndex = 0;
          for (let i = 0; i < colLetter.length; i++) {
            colIndex = colIndex * 26 + (colLetter.charCodeAt(i) - 64);
          }
          colIndex -= 1;

          const colOffset = colIndex - usedRange.columnIndex;
          if (colOffset < 0 || colOffset >= usedRange.columnCount) {
            return {
              sheet: sheet.name,
              column: colLetter,
              lastRow: null,
              message: `Column ${colLetter} is outside the sheet's used range`,
            };
          }

          // Scan from bottom up
          const values = usedRange.values as unknown[][];
          for (let r = values.length - 1; r >= 0; r--) {
            const cell = values[r][colOffset];
            if (cell !== null && cell !== undefined && cell !== "") {
              return {
                sheet: sheet.name,
                column: colLetter,
                lastRow: r + usedRange.rowIndex + 1,
              };
            }
          }

          return {
            sheet: sheet.name,
            column: colLetter,
            lastRow: null,
            message: `Column ${colLetter} is empty within the used range`,
          };
        });

      // --- Named Ranges ---

      case "listNamedRanges":
        return Excel.run(async (context) => {
          const results: Record<string, unknown>[] = [];

          // Workbook-scoped names
          const wbNames = context.workbook.names;
          wbNames.load("items/name,items/formula,items/comment,items/type,items/value");
          await context.sync();

          for (const item of wbNames.items) {
            const entry: Record<string, unknown> = {
              name: item.name,
              refersTo: item.formula,
              scope: "workbook",
              comment: item.comment || null,
            };
            try {
              if (item.type === Excel.NamedItemType.range) {
                const range = item.getRange();
                range.load("cellCount");
                await context.sync();
                if (range.cellCount === 1) {
                  entry.value = item.value;
                } else {
                  entry.value = `(range: ${range.cellCount} cells)`;
                }
              } else {
                entry.value = item.value;
              }
            } catch {
              entry.value = null;
              entry.invalid = true;
            }
            results.push(entry);
          }

          // Worksheet-scoped names
          const sheets = context.workbook.worksheets;
          sheets.load("items/name");
          await context.sync();

          for (const sheet of sheets.items) {
            const sheetNames = sheet.names;
            sheetNames.load("items/name,items/formula,items/comment,items/type,items/value");
            await context.sync();

            for (const item of sheetNames.items) {
              const entry: Record<string, unknown> = {
                name: item.name,
                refersTo: item.formula,
                scope: sheet.name,
                comment: item.comment || null,
              };
              try {
                if (item.type === Excel.NamedItemType.range) {
                  const range = item.getRange();
                  range.load("cellCount");
                  await context.sync();
                  if (range.cellCount === 1) {
                    entry.value = item.value;
                  } else {
                    entry.value = `(range: ${range.cellCount} cells)`;
                  }
                } else {
                  entry.value = item.value;
                }
              } catch {
                entry.value = null;
                entry.invalid = true;
              }
              results.push(entry);
            }
          }

          return results;
        });

      // --- Rows & Columns ---

      case "insertRows":
        await Excel.run(async (context) => {
          const sheet = action.params.sheet
            ? context.workbook.worksheets.getItem(action.params.sheet as string)
            : context.workbook.worksheets.getActiveWorksheet();
          const row = action.params.row as number;
          const count = (action.params.count as number) || 1;
          const range = sheet.getRangeByIndexes(row, 0, count, 1);
          range.insert(Excel.InsertShiftDirection.down);
          await context.sync();
        });
        break;

      case "deleteRows":
        await Excel.run(async (context) => {
          const sheet = action.params.sheet
            ? context.workbook.worksheets.getItem(action.params.sheet as string)
            : context.workbook.worksheets.getActiveWorksheet();
          const row = action.params.row as number;
          const count = (action.params.count as number) || 1;
          const range = sheet.getRangeByIndexes(row, 0, count, 1);
          range.getEntireRow().delete(Excel.DeleteShiftDirection.up);
          await context.sync();
        });
        break;

      case "insertColumns":
        await Excel.run(async (context) => {
          const sheet = action.params.sheet
            ? context.workbook.worksheets.getItem(action.params.sheet as string)
            : context.workbook.worksheets.getActiveWorksheet();
          const col = action.params.column as number;
          const count = (action.params.count as number) || 1;
          const range = sheet.getRangeByIndexes(0, col, 1, count);
          range.insert(Excel.InsertShiftDirection.right);
          await context.sync();
        });
        break;

      case "deleteColumns":
        await Excel.run(async (context) => {
          const sheet = action.params.sheet
            ? context.workbook.worksheets.getItem(action.params.sheet as string)
            : context.workbook.worksheets.getActiveWorksheet();
          const col = action.params.column as number;
          const count = (action.params.count as number) || 1;
          const range = sheet.getRangeByIndexes(0, col, 1, count);
          range.getEntireColumn().delete(Excel.DeleteShiftDirection.left);
          await context.sync();
        });
        break;

      // --- Charts ---

      case "createChart":
        await Excel.run(async (context) => {
          const sheet = action.params.sheet
            ? context.workbook.worksheets.getItem(action.params.sheet as string)
            : context.workbook.worksheets.getActiveWorksheet();
          const dataRange = sheet.getRange(action.params.dataRange as string);
          const chartType = (action.params.chartType as string) || "ColumnClustered";
          const chart = sheet.charts.add(chartType as Excel.ChartType, dataRange);
          if (action.params.title) {
            chart.title.text = action.params.title as string;
          }
          if (action.params.width) chart.width = action.params.width as number;
          if (action.params.height) chart.height = action.params.height as number;
          await context.sync();
        });
        break;

      // --- Conditional Formatting ---

      case "addConditionalFormatting":
        await Excel.run(async (context) => {
          const sheet = action.params.sheet
            ? context.workbook.worksheets.getItem(action.params.sheet as string)
            : context.workbook.worksheets.getActiveWorksheet();
          const range = sheet.getRange(action.params.address as string);
          const rule = action.params.rule as string;
          const type = (action.params.type as string) || "cellValue";

          if (type === "colorScale") {
            range.conditionalFormats.add(Excel.ConditionalFormatType.colorScale);
          } else if (type === "dataBar") {
            range.conditionalFormats.add(Excel.ConditionalFormatType.dataBar);
          } else if (type === "iconSet") {
            range.conditionalFormats.add(Excel.ConditionalFormatType.iconSet);
          } else {
            // Cell value rule
            const fmt = range.conditionalFormats.add(Excel.ConditionalFormatType.cellValue);
            const operator = (action.params.operator as string) || "greaterThan";
            const ruleConfig: Excel.ConditionalCellValueRule = {
              formula1: rule,
              operator: operator as Excel.ConditionalCellValueOperator,
            };
            if ((operator === "between" || operator === "notBetween") && action.params.rule2) {
              ruleConfig.formula2 = action.params.rule2 as string;
            }
            fmt.cellValue.rule = ruleConfig;
            if (action.params.fontColor) {
              fmt.cellValue.format.font.color = action.params.fontColor as string;
            }
            if (action.params.fillColor) {
              fmt.cellValue.format.fill.color = action.params.fillColor as string;
            }
          }
          await context.sync();
        });
        break;

      case "clearConditionalFormatting":
        await Excel.run(async (context) => {
          const sheet = action.params.sheet
            ? context.workbook.worksheets.getItem(action.params.sheet as string)
            : context.workbook.worksheets.getActiveWorksheet();
          const range = sheet.getRange(action.params.address as string);
          range.conditionalFormats.clearAll();
          await context.sync();
        });
        break;

      // --- Copy/Paste ---

      case "copyRange":
        await Excel.run(async (context) => {
          const srcSheet = action.params.sourceSheet
            ? context.workbook.worksheets.getItem(action.params.sourceSheet as string)
            : context.workbook.worksheets.getActiveWorksheet();
          const destSheet = action.params.destSheet
            ? context.workbook.worksheets.getItem(action.params.destSheet as string)
            : srcSheet;
          const source = srcSheet.getRange(action.params.source as string);
          const dest = destSheet.getRange(action.params.destination as string);
          dest.copyFrom(source);
          await context.sync();
        });
        break;

      // --- Comments ---

      case "addComment":
        await Excel.run(async (context) => {
          const sheet = action.params.sheet
            ? context.workbook.worksheets.getItem(action.params.sheet as string)
            : context.workbook.worksheets.getActiveWorksheet();
          const range = sheet.getRange(action.params.address as string);
          sheet.comments.add(range, action.params.text as string);
          await context.sync();
        });
        break;

      case "getComments":
        return Excel.run(async (context) => {
          const sheet = action.params.sheet
            ? context.workbook.worksheets.getItem(action.params.sheet as string)
            : context.workbook.worksheets.getActiveWorksheet();
          const comments = sheet.comments;
          comments.load("items/content,items/authorName,items/creationDate");
          await context.sync();
          const results = [];
          for (const c of comments.items) {
            const range = c.getLocation();
            range.load("address");
            await context.sync();
            results.push({
              content: c.content,
              author: c.authorName,
              date: c.creationDate,
              address: range.address,
            });
          }
          return results;
        });

      case "deleteComment":
        await Excel.run(async (context) => {
          const sheet = action.params.sheet
            ? context.workbook.worksheets.getItem(action.params.sheet as string)
            : context.workbook.worksheets.getActiveWorksheet();
          const range = sheet.getRange(action.params.address as string);
          const comment = sheet.comments.getItemByCell(range);
          comment.delete();
          await context.sync();
        });
        break;

      // --- Sort ---

      case "sortRange":
        await Excel.run(async (context) => {
          const sheet = action.params.sheet
            ? context.workbook.worksheets.getItem(action.params.sheet as string)
            : context.workbook.worksheets.getActiveWorksheet();
          const range = sheet.getRange(action.params.address as string);
          const colIndex = (action.params.columnIndex as number) || 0;
          const ascending = (action.params.ascending as boolean) !== false;
          range.sort.apply([{ key: colIndex, ascending }]);
          await context.sync();
        });
        break;

      // --- Merge ---

      case "mergeCells":
        await Excel.run(async (context) => {
          const sheet = action.params.sheet
            ? context.workbook.worksheets.getItem(action.params.sheet as string)
            : context.workbook.worksheets.getActiveWorksheet();
          const range = sheet.getRange(action.params.address as string);
          range.merge((action.params.across as boolean) || false);
          await context.sync();
        });
        break;

      case "unmergeCells":
        await Excel.run(async (context) => {
          const sheet = action.params.sheet
            ? context.workbook.worksheets.getItem(action.params.sheet as string)
            : context.workbook.worksheets.getActiveWorksheet();
          const range = sheet.getRange(action.params.address as string);
          range.unmerge();
          await context.sync();
        });
        break;

      // --- Pivot Tables ---

      case "createPivotTable":
        await Excel.run(async (context) => {
          const srcSheet = action.params.sourceSheet
            ? context.workbook.worksheets.getItem(action.params.sourceSheet as string)
            : context.workbook.worksheets.getActiveWorksheet();
          const sourceRange = srcSheet.getRange(action.params.sourceAddress as string);

          const pivotName = action.params.pivotName as string;

          // Create a new sheet for the pivot table
          const destSheet = context.workbook.worksheets.add(pivotName);
          const destCell = destSheet.getRange("A1");

          const pivotTable = context.workbook.pivotTables.add(pivotName, sourceRange, destCell);

          // Add row fields
          const rows = action.params.rows as string[];
          for (const row of rows) {
            pivotTable.rowHierarchies.add(pivotTable.hierarchies.getItem(row));
          }

          // Add column fields
          const columns = (action.params.columns as string[]) || [];
          for (const col of columns) {
            pivotTable.columnHierarchies.add(pivotTable.hierarchies.getItem(col));
          }

          // Add value fields
          const values = action.params.values as Array<{ name: string; function?: string }>;
          const fnMap: Record<string, Excel.AggregationFunction> = {
            sum: Excel.AggregationFunction.sum,
            count: Excel.AggregationFunction.count,
            average: Excel.AggregationFunction.average,
            max: Excel.AggregationFunction.max,
            min: Excel.AggregationFunction.min,
          };
          for (const val of values) {
            const dataHierarchy = pivotTable.dataHierarchies.add(pivotTable.hierarchies.getItem(val.name));
            if (val.function && fnMap[val.function]) {
              dataHierarchy.summarizeBy = fnMap[val.function];
            }
          }

          destSheet.activate();
          await context.sync();
        });
        break;

      default:
        console.warn(`Unknown action type: ${action.type}`);
    }
    return undefined;
  },
};

// Helper: convert 0-based column index to Excel column letter (0→A, 25→Z, 26→AA, 701→ZZ, 702→AAA)
function colIndexToLetter(index: number): string {
  let result = "";
  let i = index;
  while (i >= 0) {
    result = String.fromCharCode(65 + (i % 26)) + result;
    i = Math.floor(i / 26) - 1;
  }
  return result;
}

// Helper: convert cell address like "A1" to { row: 0, col: 0 }
function cellToRowCol(cell: string): { row: number; col: number } {
  const match = cell.match(/^\$?([A-Z]+)\$?(\d+)$/i);
  if (!match) throw new Error(`Invalid cell address: "${cell}"`);
  const colStr = match[1].toUpperCase();
  const row = parseInt(match[2], 10) - 1;
  let col = 0;
  for (let i = 0; i < colStr.length; i++) {
    col = col * 26 + (colStr.charCodeAt(i) - 64);
  }
  return { row, col: col - 1 };
}
