import * as React from "react";

interface ChatInputProps {
  onSend: (message: string) => void;
  disabled?: boolean;
  statusText?: string;
  onSettingsClick?: () => void;
  onStop?: () => void;
}

const ChatInput: React.FC<ChatInputProps> = ({ onSend, disabled, statusText, onSettingsClick, onStop }) => {
  const [value, setValue] = React.useState("");

  const handleSubmit = (e?: React.FormEvent) => {
    e?.preventDefault();
    const trimmed = value.trim();
    if (!trimmed || disabled) return;
    onSend(trimmed);
    setValue("");
  };

  const handleKeyDown = (e: React.KeyboardEvent<HTMLTextAreaElement>) => {
    if (e.key === "Enter" && !e.shiftKey) {
      e.preventDefault();
      handleSubmit();
    }
  };

  return (
    <form onSubmit={handleSubmit} className="bg-background p-3">
      <div className="rounded-lg border border-input shadow-xs focus-within:border-ring focus-within:ring-2 focus-within:ring-ring/50">
        <textarea
          value={value}
          onChange={(e) => setValue(e.target.value)}
          onKeyDown={handleKeyDown}
          placeholder="Send a message..."
          disabled={disabled}
          rows={2}
          className="w-full min-h-[56px] max-h-[200px] resize-none bg-background px-3 py-2.5 text-sm text-foreground placeholder-muted-foreground outline-none rounded-t-lg"
        />
        <div className="flex items-center justify-between bg-background px-2 py-1.5 rounded-b-lg">
          <div className="flex items-center gap-1">
            {onSettingsClick && (
              <button
                type="button"
                onClick={onSettingsClick}
                className="flex h-7 w-7 items-center justify-center rounded-md text-muted-foreground transition-colors hover:bg-accent hover:text-foreground"
              >
                <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                  <circle cx="12" cy="12" r="3" />
                  <path d="M12 1v2M12 21v2M4.22 4.22l1.42 1.42M18.36 18.36l1.42 1.42M1 12h2M21 12h2M4.22 19.78l1.42-1.42M18.36 5.64l1.42-1.42" />
                </svg>
              </button>
            )}
            {statusText && (
              <span className="text-[11px] text-muted-foreground">{statusText}</span>
            )}
          </div>
          <div className="flex items-center gap-1">
            {disabled && onStop ? (
              <button
                type="button"
                onClick={onStop}
                className="flex h-7 w-7 items-center justify-center rounded-md text-destructive transition-colors hover:bg-destructive/10"
              >
                <svg width="14" height="14" viewBox="0 0 24 24" fill="currentColor">
                  <rect x="4" y="4" width="16" height="16" rx="2" />
                </svg>
              </button>
            ) : (
              <button
                type="submit"
                disabled={disabled || !value.trim()}
                className="flex h-7 w-7 items-center justify-center rounded-md text-primary transition-colors hover:bg-accent disabled:opacity-30"
              >
                <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                  <line x1="12" y1="19" x2="12" y2="5" />
                  <polyline points="5 12 12 5 19 12" />
                </svg>
              </button>
            )}
          </div>
        </div>
      </div>
    </form>
  );
};

export default ChatInput;
