/**
 * WebSocket client for server-side Claude orchestration.
 *
 * Maintains a persistent WebSocket connection to the FastAPI /chat endpoint.
 * The server holds conversation history across messages within one connection.
 */

import { OfficeAction, WebSource } from "../types";

export interface ChatResult {
  text: string;
  toolsUsed: string[];
  sources: WebSource[];
}

export type ToolExecutor = (action: OfficeAction) => Promise<unknown>;
export type StatusCallback = (status: string) => void;

// Default API URL — overridden when Tauri provides the sidecar config
let _apiWsUrl = "wss://localhost:1997/chat";
let _authToken = "";

export function setApiConfig(wsUrl: string, authToken: string): void {
  _apiWsUrl = wsUrl;
  _authToken = authToken;
}

export function getApiWsUrl(): string {
  return _apiWsUrl;
}

/**
 * Persistent WebSocket connection that preserves conversation history
 * across multiple messages within a single session.
 */
export class ChatConnection {
  private ws: WebSocket | null = null;
  private connecting: Promise<void> | null = null;

  // Per-message state — set by sendMessage, used by onmessage handler
  private currentResolve: ((result: ChatResult) => void) | null = null;
  private currentReject: ((err: Error) => void) | null = null;
  private currentExecuteAction: ToolExecutor | null = null;
  private currentOnStatus: StatusCallback | null = null;
  private lastResponseText = "";
  private toolsUsed: string[] = [];
  private sources: WebSource[] = [];

  /**
   * Ensure the WebSocket is connected. Reuses existing connection if open.
   */
  private ensureConnected(): Promise<void> {
    if (this.ws && this.ws.readyState === WebSocket.OPEN) {
      return Promise.resolve();
    }
    if (this.connecting) {
      return this.connecting;
    }

    this.connecting = new Promise<void>((resolve, reject) => {
      const url = _authToken
        ? `${_apiWsUrl}?token=${encodeURIComponent(_authToken)}`
        : _apiWsUrl;

      const ws = new WebSocket(url);

      ws.onopen = () => {
        this.ws = ws;
        this.connecting = null;
        resolve();
      };

      ws.onerror = () => {
        this.ws = null;
        this.connecting = null;
        reject(new Error("WebSocket connection failed. Is the Bluebook desktop app running?"));
      };

      ws.onclose = () => {
        this.ws = null;
        this.connecting = null;
        // If there's a pending message, reject it
        if (this.currentReject) {
          this.currentReject(new Error("Connection closed unexpectedly"));
          this.clearMessageState();
        }
      };

      ws.onmessage = async (event) => {
        let msg: Record<string, unknown>;
        try {
          msg = JSON.parse(event.data as string);
        } catch {
          return;
        }

        switch (msg.type) {
          case "status":
            this.currentOnStatus?.(msg.text as string);
            break;

          case "response":
            this.lastResponseText = msg.text as string;
            break;

          case "tool_calls": {
            if (!this.currentExecuteAction) break;
            const calls = msg.calls as Array<{
              id: string;
              action: { type: string; params: Record<string, unknown> };
            }>;

            const results: Array<{
              id: string;
              result?: unknown;
              error?: string;
            }> = [];

            for (const call of calls) {
              try {
                const result = await this.currentExecuteAction(call.action as OfficeAction);
                results.push({ id: call.id, result: result ?? null });
              } catch (err) {
                results.push({
                  id: call.id,
                  error: err instanceof Error ? err.message : "Unknown error",
                });
              }
            }

            if (this.ws && this.ws.readyState === WebSocket.OPEN) {
              this.ws.send(JSON.stringify({ type: "tool_results", results }));
            }
            break;
          }

          case "sources":
            this.sources = (msg.sources as WebSource[]) || [];
            break;

          case "done":
            this.toolsUsed = (msg.toolsUsed as string[]) || [];
            if (this.currentResolve) {
              this.currentResolve({
                text: this.lastResponseText,
                toolsUsed: this.toolsUsed,
                sources: this.sources,
              });
            }
            this.clearMessageState();
            break;

          case "error":
            if (this.currentReject) {
              this.currentReject(new Error(msg.message as string));
            }
            this.clearMessageState();
            break;
        }
      };
    });

    return this.connecting;
  }

  private clearMessageState(): void {
    this.currentResolve = null;
    this.currentReject = null;
    this.currentExecuteAction = null;
    this.currentOnStatus = null;
    this.lastResponseText = "";
    this.toolsUsed = [];
    this.sources = [];
  }

  /**
   * Send a message over the persistent connection.
   * Returns a promise that resolves with the assistant's response.
   */
  async sendMessage(
    app: "word" | "excel" | "powerpoint",
    message: string,
    selectedContent: string | null,
    executeAction: ToolExecutor,
    onStatus?: StatusCallback,
    signal?: AbortSignal,
    slideImage?: string | null,
    documentName?: string | null,
    documentPath?: string | null,
  ): Promise<ChatResult> {
    await this.ensureConnected();

    return new Promise<ChatResult>((resolve, reject) => {
      // Set per-message state
      this.currentResolve = resolve;
      this.currentReject = reject;
      this.currentExecuteAction = executeAction;
      this.currentOnStatus = onStatus ?? null;
      this.lastResponseText = "";
      this.toolsUsed = [];
      this.sources = [];

      // Abort support
      if (signal) {
        if (signal.aborted) {
          this.clearMessageState();
          reject(new DOMException("Aborted", "AbortError"));
          return;
        }
        signal.addEventListener("abort", () => {
          if (this.ws && this.ws.readyState === WebSocket.OPEN) {
            this.ws.send(JSON.stringify({ type: "abort" }));
          }
          if (this.currentReject) {
            this.currentReject(new DOMException("Aborted", "AbortError"));
          }
          this.clearMessageState();
        }, { once: true });
      }

      this.ws!.send(JSON.stringify({
        type: "start",
        app,
        message,
        selectedContent: selectedContent || undefined,
        slideImage: slideImage || undefined,
        documentName: documentName || undefined,
        documentPath: documentPath || undefined,
      }));
    });
  }

  /** Close the connection and reset conversation history. */
  disconnect(): void {
    if (this.ws) {
      this.ws.close();
      this.ws = null;
    }
    this.clearMessageState();
  }
}
