import { ChatRequest, ChatResponse, ChatMessage } from "../types";

function generateId(): string {
  return Date.now().toString(36) + Math.random().toString(36).slice(2);
}

function createMockResponse(userMessage: string): ChatMessage {
  const responses = [
    "I can help you with that! This is a mock response — once the FastAPI backend is connected, I'll provide real AI-powered answers.",
    `You said: "${userMessage}". I'm currently running in mock mode. The real AI backend will be available soon.`,
    "Great question! I'm a placeholder response for now. The actual AI service will handle this once the API is set up.",
  ];
  return {
    id: generateId(),
    role: "assistant",
    content: responses[Math.floor(Math.random() * responses.length)],
    timestamp: Date.now(),
  };
}

export function createChatClient(baseUrl?: string) {
  return {
    async sendMessage(request: ChatRequest): Promise<ChatResponse> {
      if (!baseUrl) {
        // Mock mode — simulate a delay and return a fake response
        await new Promise((resolve) => setTimeout(resolve, 800));
        const lastUserMsg = request.messages[request.messages.length - 1];
        return {
          message: createMockResponse(lastUserMsg?.content ?? ""),
        };
      }

      const res = await fetch(`${baseUrl}/chat`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(request),
      });

      if (!res.ok) {
        throw new Error(`Chat API error: ${res.status}`);
      }

      return res.json();
    },
  };
}
