import * as React from "react";
import ReactMarkdown from "react-markdown";
import remarkGfm from "remark-gfm";
import { ChatMessage as ChatMessageType, WebSource } from "../types";

function getDomain(url: string): string {
  try {
    return new URL(url).hostname.replace(/^www\./, "");
  } catch {
    return url;
  }
}

const SourceBadge: React.FC<{ source: WebSource }> = ({ source }) => (
  <a
    href={source.url}
    target="_blank"
    rel="noopener noreferrer"
    title={source.title || source.url}
    className="inline-flex items-center gap-1.5 px-2 py-1 rounded-md bg-muted hover:bg-muted/70 text-xs text-muted-foreground transition-colors max-w-[200px]"
  >
    <img
      src={`https://www.google.com/s2/favicons?domain=${getDomain(source.url)}&sz=32`}
      alt=""
      className="w-3.5 h-3.5 rounded-sm shrink-0"
    />
    <span className="truncate">
      {source.title || getDomain(source.url)}
    </span>
  </a>
);

interface ChatMessageProps {
  message: ChatMessageType;
}

const ChatMessage: React.FC<ChatMessageProps> = ({ message }) => {
  const isUser = message.role === "user";

  return (
    <div className="border-b border-border/50">
      <div className="flex gap-3 py-3 px-4">
        {/* Status indicator dot */}
        <div className="flex items-start pt-[9px]">
          <div
            className={`w-2 h-2 rounded-full shrink-0 ${
              isUser
                ? "bg-primary"
                : message.isStreaming
                  ? "bg-accent-foreground animate-pulse"
                  : "bg-accent-foreground"
            }`}
          />
        </div>

        {/* Message content */}
        <div className="flex-1 min-w-0">
          <div className="mb-0.5">
            <span className="text-sm font-medium text-muted-foreground">
              {isUser ? "You" : "Assistant"}
            </span>
          </div>

          {!message.isStreaming && <div className="text-sm text-foreground break-words max-w-none">
            <ReactMarkdown
              remarkPlugins={[remarkGfm]}
              components={{
                p: ({ children }) => (
                  <p className="mb-3 last:mb-0 leading-relaxed">{children}</p>
                ),
                ul: ({ children }) => (
                  <ul className="mb-2 last:mb-0 list-disc ml-4">{children}</ul>
                ),
                ol: ({ children }) => (
                  <ol className="mb-2 last:mb-0 list-decimal ml-4">{children}</ol>
                ),
                code: ({ children, className }) => {
                  const isBlock = className?.includes("language-");
                  if (isBlock) {
                    return (
                      <pre className="mb-2 rounded-md bg-muted p-3 overflow-x-auto">
                        <code className="text-xs font-mono">{children}</code>
                      </pre>
                    );
                  }
                  return (
                    <code className="rounded bg-muted px-1 py-0.5 text-xs font-mono">
                      {children}
                    </code>
                  );
                },
                pre: ({ children }) => <>{children}</>,
              }}
            >
              {message.content}
            </ReactMarkdown>
            {message.sources && message.sources.length > 0 && (
              <div className="flex flex-wrap gap-1.5 mt-2">
                {message.sources.map((source, i) => (
                  <SourceBadge key={i} source={source} />
                ))}
              </div>
            )}
          </div>}

          {message.isStreaming && (
            <span className="inline-flex items-center gap-1.5 mt-1">
              <svg
                className="animate-spin h-3 w-3 text-primary"
                xmlns="http://www.w3.org/2000/svg"
                fill="none"
                viewBox="0 0 24 24"
              >
                <circle
                  className="opacity-25"
                  cx="12"
                  cy="12"
                  r="10"
                  stroke="currentColor"
                  strokeWidth="4"
                />
                <path
                  className="opacity-75"
                  fill="currentColor"
                  d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"
                />
              </svg>
              <span className="text-sm text-muted-foreground">
                {message.content || "Thinking..."}
              </span>
            </span>
          )}
        </div>
      </div>
    </div>
  );
};

export default ChatMessage;
