import * as React from "react";
import { OfficeAdapter } from "../types";

export const OfficeAdapterContext = React.createContext<OfficeAdapter | null>(null);

export function useOfficeAdapter(): OfficeAdapter {
  const adapter = React.useContext(OfficeAdapterContext);
  if (!adapter) {
    throw new Error("useOfficeAdapter must be used within an OfficeAdapterContext.Provider");
  }
  return adapter;
}
