import { getApiWsUrl } from "./websocket-client";

/**
 * Derive the HTTP base URL from the WebSocket URL.
 * wss://localhost:8000/chat -> https://localhost:8000
 * ws://127.0.0.1:9999/chat -> http://127.0.0.1:9999
 */
function getSyncBaseUrl(): string {
  const wsUrl = getApiWsUrl();
  return wsUrl
    .replace(/^wss:/, "https:")
    .replace(/^ws:/, "http:")
    .replace(/\/chat$/, "");
}

function simpleDiff(before: string, after: string): string {
  if (!before) return "(new document)";
  if (before === after) return "(no changes)";

  const beforeLines = before.split("\n");
  const afterLines = after.split("\n");
  const diffs: string[] = [];

  const maxLen = Math.max(beforeLines.length, afterLines.length);
  for (let i = 0; i < maxLen; i++) {
    const b = beforeLines[i];
    const a = afterLines[i];
    if (b === undefined) {
      diffs.push(`+ ${a}`);
    } else if (a === undefined) {
      diffs.push(`- ${b}`);
    } else if (b !== a) {
      diffs.push(`- ${b}`);
      diffs.push(`+ ${a}`);
    }
  }

  return diffs.slice(0, 100).join("\n") + (diffs.length > 100 ? "\n... (truncated)" : "");
}

export async function syncDocumentSnapshot(
  path: string,
  name: string,
  contentBefore: string,
  contentAfter: string,
  actionsSummary: string,
): Promise<string> {
  const diff = simpleDiff(contentBefore, contentAfter);
  const syncUrl = `${getSyncBaseUrl()}/cowork/sync`;

  try {
    const res = await fetch(syncUrl, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        path,
        name,
        content: contentAfter,
        diff,
        actions_summary: actionsSummary,
      }),
    });
    return `Synced (${res.status})`;
  } catch (err) {
    return `Sync failed: ${err instanceof Error ? err.message : String(err)}`;
  }
}
